import {Model,W,H,STEP,clamp} from './model.js';
import {render} from './render.js';
const settings={gravity:['Гравитация g',0,600,10,'px/s² · больше — сильнее падение'],restitution:['Упругость e',0,1,.05,'0 — без отскока; 1 — упругий удар'],damping:['Затухание',0,5,.1,'1/s · больше — быстрее теряется скорость'],stiffness:['Жёсткость пружины k',5,100,5,'условные единицы · больше — сильнее возврат'],power:['Сила запуска',1,6,.25,'больше — выше стартовая скорость'],speed:['Скорость',20,200,10,'px/s · постоянная скорость по x'],voltage:['Напряжение U',0,12,.5,'V · идеальный источник'],resistance:['Сопротивление R',20,500,10,'Ω · больше — меньше ток'],field:['Сила поля',0,600,10,'условные единицы · больше — сильнее притяжение']};
export function mountScene(root,id){const m=new Model(id);let running=false,last=0,acc=0,selection=0,mode='launch',first=null;
 root.innerHTML=`<div class="canvas-wrap"><canvas tabindex="0" aria-label="Интерактивная сцена. Стрелки перемещают цель, пробел запускает или ставит на паузу."></canvas></div><div class="toolbar"><button data-act="run">Запустить</button><button data-act="reset">Сбросить сцену</button><button data-act="step">Один шаг</button></div><p class="scene-status" aria-label="Состояние сцены"></p><div class="controls"></div>`;
 const canvas=root.querySelector('canvas'),ctx=canvas.getContext('2d'),status=root.querySelector('.scene-status'),controls=root.querySelector('.controls');
 let keys=id===11?['voltage','resistance']:id===3?['speed']:id===12?['field','damping']:id<=2?[]:id===4?['damping']:id===13?['gravity','field','damping']:['gravity','restitution','damping',...([6,8,9,14].includes(id)?['stiffness']:[]),...([10,14].includes(id)?['power']:[])];
 for(const key of keys){const [name,min,max,step,help]=settings[key];const label=document.createElement('label');label.innerHTML=`${name}: <output>${m.params[key]}</output><input type="range" min="${min}" max="${max}" step="${step}" value="${m.params[key]}" aria-label="${name}"><small>${help}</small>`;label.querySelector('input').addEventListener('input',e=>{m.params[key]=Number(e.target.value);label.querySelector('output').value=e.target.value;if(key==='speed')m.balls[0].vx=m.params.speed;paint();});controls.append(label);}
 if(id===11){const b=document.createElement('button');b.textContent='Разомкнуть цепь';b.onclick=()=>{m.closed=!m.closed;b.textContent=m.closed?'Разомкнуть цепь':'Замкнуть цепь';paint();};controls.append(b);canvas.addEventListener('click',()=>b.click());}
 if([9,14].includes(id)){const box=document.createElement('div');box.className='link-tools';box.innerHTML=`<label>Режим <select aria-label="Режим взаимодействия"><option value="launch">${id===14?'Рогатка':'Перетаскивание'}</option><option value="connect">Связать два шара</option></select></label><label>Выбранная связь <select aria-label="Выбранная связь" data-links></select></label><button>Переключить мягкая / жёсткая</button>`;controls.append(box);box.querySelector('select').onchange=e=>{mode=e.target.value;first=null;};const list=box.querySelector('[data-links]');const refresh=()=>{list.innerHTML=m.links.map((l,i)=>`<option value="${i}">${i+1}: ${l.a+1} ↔ ${l.b+1} (${l.type==='soft'?'мягкая':'жёсткая'})</option>`).join('');list.value=String(selection);};list.onchange=()=>{selection=Number(list.value);paint();};box.querySelector('button').onclick=()=>{const l=m.links[selection];if(l){l.type=l.type==='soft'?'rigid':'soft';refresh();paint();}};root.refreshLinks=refresh;refresh();canvas.addEventListener('contextmenu',e=>{e.preventDefault();const p=position(e);let nearest=Infinity;m.links.forEach((l,i)=>{const a=m.balls[l.a],b=m.balls[l.b],dx=b.x-a.x,dy=b.y-a.y,t=clamp(((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy||1),0,1),d=Math.hypot(p.x-a.x-dx*t,p.y-a.y-dy*t);if(d<nearest){nearest=d;selection=i;}});if(nearest<30)box.querySelector('button').click();});}
 function paint(){render(ctx,m,selection);status.textContent=id===11?`Ток ${(m.current()*1000).toFixed(1)} mA. Маркеры показывают условный ток, а не электроны.`:[10,14].includes(id)?`Попадания: ${m.score}. Запуски: ${m.shots}. ${m.scored?'Попадание!':''} ${first!==null?'Выберите второй шар.':''}`:`${running?'Сцена работает':'Пауза'} · t = ${m.time.toFixed(2)} s · x = ${m.balls[0].x.toFixed(1)} · y = ${m.balls[0].y.toFixed(1)}`;}
 function resize(){const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0);paint();}new ResizeObserver(resize).observe(canvas);
 function run(value){running=value;last=0;acc=0;root.querySelector('[data-act=run]').textContent=value?'Пауза':'Запустить';paint();}
 root.querySelector('[data-act=run]').onclick=()=>run(!running);root.querySelector('[data-act=reset]').onclick=()=>{run(false);m.reset();selection=0;first=null;root.refreshLinks?.();paint();};root.querySelector('[data-act=step]').onclick=()=>{run(false);m.step();paint();};
 function position(e){const r=canvas.getBoundingClientRect();return {x:clamp((e.clientX-r.left)*W/r.width,16,W-16),y:clamp((e.clientY-r.top)*H/r.height,16,H-16)};}
 canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;const p=position(e);m.target=p;let index=m.balls.findIndex(b=>!b.fixed&&Math.hypot(b.x-p.x,b.y-p.y)<34);if(id===1){m.balls[0].x=p.x;m.balls[0].y=p.y;}else if(id===4){m.balls[0].vx+=(p.x-m.balls[0].x)*3;m.balls[0].vy+=(p.y-m.balls[0].y)*3;}else if(mode==='connect'&&index>=0){if(first===null)first=index;else{m.addLink(first,index);first=null;root.refreshLinks?.();}}else if(index>=0 && id!==11){const b=m.balls[index];m.drag={index,anchor:{x:b.x,y:b.y},pointer:p};canvas.setPointerCapture(e.pointerId);}paint();});
 canvas.addEventListener('pointermove',e=>{const p=position(e);if([1,2,12,13].includes(id))m.target=p;if(id===1 && e.buttons){m.balls[0].x=p.x;m.balls[0].y=p.y;}if(m.drag){m.drag.pointer=p;if(![10,14].includes(id)){const b=m.balls[m.drag.index];b.x=p.x;b.y=p.y;b.vx=0;b.vy=0;}}paint();});
 function release(e){if(!m.drag)return;if([10,14].includes(id)&&e.type!=='pointercancel'){const d=m.drag;m.launch(d.index,d.pointer,d.anchor);run(true);}else m.drag=null;paint();}canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);
 canvas.addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();run(!running);}const moves={ArrowLeft:[-20,0],ArrowRight:[20,0],ArrowUp:[0,-20],ArrowDown:[0,20]};if(moves[e.key]){e.preventDefault();m.target.x=clamp(m.target.x+moves[e.key][0],16,W-16);m.target.y=clamp(m.target.y+moves[e.key][1],16,H-16);if(id===1)Object.assign(m.balls[0],m.target);paint();}if(e.key==='Enter'&&[10,14].includes(id)){const b=m.balls[0];m.launch(0,{x:b.x-100,y:b.y+50},{x:b.x,y:b.y});run(true);}});
 document.addEventListener('visibilitychange',()=>{if(document.hidden)run(false);});const observer=new IntersectionObserver(entries=>{if(!entries[0].isIntersecting)run(false);});observer.observe(canvas);
 function frame(t){if(running){const delta=last?Math.min((t-last)/1000,.05):0;last=t;acc+=delta;let steps=0;while(acc>=STEP&&steps++<6){m.step();acc-=STEP;}paint();}requestAnimationFrame(frame);}requestAnimationFrame(frame);resize();return m;}
